\label {D1}
\begin{enumerate}

\@par\hangindent 2em A commutative  graded algebra   abbreviated CGA,   is  an associative unital augmentable graded algebra $\mathcal A^\ast,$ (the augmentation is not part of the data)  which is commutative in the graded sense, i.e.
 \begin{equation*}
a_1\cdot a_2= (-1)^{r_1  r_2}a_2\cdot a_1,\ \ 
a_i\in \mathcal A^{r_i}, i=1,2.
\end{equation*}

 \@par\hangindent 2em An exterior  differential $d^\ast_\mathcal A: \mathcal A^\ast \to \mathcal A^{\ast+1},$  is a degree +1-linear map which satisfies

\begin{equation*}
 d(a_1\cdot a_2)= d(a_1)\cdot a_2 +(-1)^{r_1} a_1\cdot d(a_2),  a_1\in \mathcal A^{r_1} ,\ \ 
d^{*+1}_{\mathcal  A} d^{*}_{\mathcal  A}=0.
\end{equation*}  

\@par\hangindent 2em An interior differential $\beta^\mathcal A_\ast : \mathcal A^\ast\to \mathcal A^{\ast-1}$ is a degree -1 linear map which satisfies  

\begin{equation*}
\beta(a_1\cdot a_2)= \beta(a_1)\cdot a_2 +(-1)^{r_1} a_1\cdot \beta(a_2),   a_1\in \mathcal A^{r_1},  \ \ 
\beta_{\ast-1}^{\mathcal  A} \beta_{\ast}^{\mathcal  A}=0.
\end{equation*}

\@par\hangindent 2em The exterior and interior differentials $d^\ast$ and $\beta_\ast$ are compatible if 
\begin{equation*}
d^{\ast-1}\cdot \beta_\ast +\beta_{\ast+1}\cdot d^\ast=0.
\end{equation*}

\@par\hangindent 2em A pair $(\mathcal A^\ast, d^\ast),\ \mathcal A^\ast$ a CGA and   $d^\ast$  exterior differential, is called CDGA  and a triple $(\mathcal A^\ast, d^\ast, \beta_\ast),\   \mathcal A^\ast$ a CGA,  $d^\ast$  exterior differential and $\beta_\ast$ interior differential,
with $d^\ast$ and $\beta_\ast$ compatible,  is called a mixed  CDGA.
\end{enumerate}

\label{O2}
 The vector space $K^\ast(P)$ can be identified via the Chern character to the Atiyah--Hirtzebruch (complex) $K-$theory tensored with the field $\kappa= \mathbb R \text{or} \ \mathbb C,$ depending of what sort of differential forms one consider (real or complex valued).  When $P$ is 1-connected $\overline cH^\ast (P)$ identifies to $\text{Hom}(\tilde A_{\ast}(P), k)$ where $\tilde A_{\ast}(P)$
denotes the reduced Waldhaussen algebraic  $K-$theory\footnote {often referred to as $A-$ theory.}, cf \@nx\protect\@empty\@nx\csname cite \endcsname{B2}. From this perspective $sH^\ast$ unifies topological (Atiyah--Hirtzebruch) $K-$theory  and Waldhaussen algebraic $K-$theory.

\label{T4}
Let $(\mathcal A, d_\mathcal A)$ be a connected CDGA. 

1. All  eigenvalues of the endomorphisms $ H\Psi_k$ and $ C\Psi_k$ are $k^r, r=0,1, 2\cdots,$ and their eigenspaces  are independent of $k$  provided  $k\geq 2.$
One denotes them by $HH(\mathcal A, d_\mathcal A)(r),$ and  $ CH(\mathcal A, d_\mathcal A)(r).$

2. \begin{equation*}
\begin{aligned}
HH^\ast(\mathcal A, d_\mathcal A)(0)=&H^\ast(\mathcal A, d_\mathcal A), \\
  CH^\ast(\mathcal A, d_\mathcal A)(0)= &H^{\ast+1}(\mathcal A, d_\mathcal A)\\
HH^r(\mathcal A, d_\mathcal A)(p)= &CH^r(\mathcal A, d_\mathcal A)(p)=0, \ \   p\geq r+1
\end{aligned}
\end{equation*}

3.Suppose  $(\mathcal A, d_\mathcal A)$ is 1-connected with minimal model $(\Lambda[V], d_V).$
If  $ \sum_i\dim V^i< \infty$ and $\sum_i \dim H^i(\mathcal A, d_\mathcal A) <\infty$ then for any $r\geq 0$ one has 
$$\sum_i \dim HH^i(\mathcal A, d_\mathcal A)(r) < \infty, \ \ \sum_i\dim CH^i(\mathcal A, d_\mathcal A)(r) < \infty.$$
